0\u043b\u044c\u0444\u0430 \u0432 \u0431\u0435\u043b\u043e\u043c \u043e\u0431\u043b\u0438\u0447\u044c\u0438 (\u0438, \u043a \u0441\u043b\u043e\u0432\u0443, \u043e\u043d \u043c\u043d\u0435 \u0431\u043e\u043b\u044c\u0448\u0435 \u043d\u0440\u0430\u0432\u0438\u0442\u0441\u044f \u0441\u0435\u0440\u044b\u043c.) - \u041e\u043d \u0441\u043b\u043e\u0432\u043d\u043e \u0441\u0442\u0430\u043b \u0435\u0449\u0451 \u043c\u0443\u0434\u0440\u0435\u0439, \u0430 \u0442\u0430\u043a\u0436\u0435 \u0431\u0443\u0434\u0442\u043e \u0441\u0442\u0430\u043b \u0441\u0438\u044f\u0442\u044c. \u041f\u0440\u043e\u043b\u043e\u0433 - \u0432\u0435\u0441\u044c\u043c\u0430 \u0437\u0440\u0435\u043b\u0438\u0449\u043d\u043e. \u041e\u0440\u043a\u0438 - \u043d\u0443 \u043f\u0440\u043e\u0441\u0442\u043e \"\u043a\u0440\u0430\u0441\u0430\u0432\u0446\u044b\". \u042d\u043d\u0442\u044b - \u043a\u0440\u0443\u0442\u043e, - \u0438 \u043e\u0447\u0435\u043d\u044c \u043a\u043b\u0430\u0441\u0441\u043d\u043e \u043e\u043d\u0438 \u0433\u043e\u0432\u043e\u0440\u044f\u0442. \u0421\u0442\u0440\u0430\u043d\u0430 \u0420\u043e\u0445\u0430\u043d - \u043e\u0442\u043b\u0438\u0447\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u043d\u043e\u0441 \u0441 \u043a\u043d\u0438\u0433\u0438 \u043d\u0430 \u044d\u043a\u0440\u0430\u043d. \u0425\u043e\u0440\u043e\u0448 \u0438 \u0435\u0433\u043e \u043a\u043e\u043d\u0443\u043d\u0433 - \u0422\u0435\u043e\u0434\u0435\u043d \u0420\u043e\u0445\u0430\u043d\u0441\u043a\u0438\u0439, \u0430 \u0435\u0433\u043e \u043f\u0435\u0440\u0435\u0432\u043e\u043f\u043b\u043e\u0449\u0435\u043d\u0438\u0435 - \u043f\u0440\u043e\u0441\u0442\u043e \u0432\u0435\u0440\u0445 \u043a\u043e\u043c\u043f\u044c\u044e\u0442\u0435\u0440\u043d\u043e\u0439 \u0433\u0440\u0430\u0444\u0438\u043a\u0438. \u0412\u0441\u0435 \u0430\u043a\u0442\u0451\u0440\u044b \u0438\u0433\u0440\u0430\u044e\u0442 \u0445\u043e\u0440\u043e\u0448\u043e, \u0441\u043a\u0430\u0436\u0443 \u0441\u0440\u0430\u0437\u0443, \u0442\u0430\u043a \u0447\u0442\u043e \u043f\u0440\u0438\u0434\u0438\u0440\u0430\u0442\u044c\u0441\u044f \u043d\u0435 \u043a \u0447\u0435\u043c\u0443. \u041c\u043e\u0439 \u043b\u044e\u0431\u0438\u043c\u044b\u0439 \u044d\u043f\u0438\u0437\u043e\u0434 \u0438\u0437 \u0444\u0438\u043b\u044c\u043c\u0430 - \u0431\u0438\u0442\u0432\u0430 \u0437\u0430 \u0425\u0435\u043b\u044c\u043c\u043e\u0432\u0443 \u041f\u0430\u0434\u044c, - \u0435\u0451 \u044f \u0441\u0447\u0438\u0442\u0430\u044e \u043b\u0443\u0447\u0448\u0438\u043c \u0432\u043e\u043f\u043b\u043e\u0449\u0435\u043d\u0438\u0435\u043c \u043e\u0441\u0430\u0434\u044b \u043a\u0440\u0435\u043f\u043e\u0441\u0442\u0438 \u043d\u0430 \u044d\u043a\u0440\u0430\u043d\u0435. \u0421\u043d\u044f\u0442\u043e \u044d\u0442\u043e \u043e\u0447\u0435\u043d\u044c \u0430\u0442\u043c\u043e\u0441\u0444\u0435\u0440\u043d\u043e, \u0438 \u0441\u043e\u0437\u0434\u0430\u0451\u0442\u0441\u044f \u043e\u0449\u044e\u0449\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u044f. \u041a\u043e\u0433\u0434\u0430 \u043f\u0430\u0434\u0430\u0435\u0442 \u043b\u0435\u0441\u0442\u043d\u0438\u0446\u0430, \u0438 \u043a\u0430\u043c\u0435\u0440\u0430 \u043d\u0430\u043a\u043b\u043e\u043d\u044f\u0435\u0442\u0441\u044f, \u0437\u0430\u0445\u0432\u0430\u0442\u044b\u0432\u0430\u0435\u0442 \u0434\u0443\u0445... - \u041e\u0441\u043e\u0431\u0435\u043d\u043d\u043e, \u0435\u0441\u043b\u0438 \u0441\u043c\u043e\u0442\u0440\u0435\u0442\u044c \u0432 \u0442\u0435\u043c\u043d\u043e\u0442\u0435 \u0438 \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u043e\u043c \u044d\u043a\u0440\u0430\u043d\u0435. \u0410\u0440\u0430\u0433\u043e\u0440\u043d \u0436\u0435 \u0432 \u044d\u0442\u043e\u0439 \u0431\u0438\u0442\u0432\u0435 \u043e\u0447\u0435\u043d\u044c \u0432\u043e\u043e\u0434\u0443\u0448\u0435\u0432\u043b\u044f\u0435\u0442. \u041b\u044e\u0431\u0438\u043c\u0430\u044f \u0435\u0433\u043e \u0444\u0440\u0430\u0437\u0430: \"\u041d\u0430\u0434\u0435\u0436\u0434\u0430 \u0432\u0441\u0435\u0433\u0434\u0430 \u0435\u0441\u0442\